  private static byte[] hex(String value){byte[] raw=new byte[value.length()/2];for(int n=0;n<raw.length;n++)raw[n]=(byte)Integer.parseInt(value.substring(n*2,n*2+2),16);return raw;}
  public static int run()throws Exception{int count=0;for(String[] v:VECTORS){byte[] raw=hex(v[0]),before=raw.clone();if(!Arrays.equals(Pc1TextExpander.decodeEncoded(raw,2048),hex(v[1])))throw new AssertionError("411E83 conversion "+v[0]);count++;if(!Arrays.equals(raw,before))throw new AssertionError("Raw code bytes changed");count++;}return count;}
